import {config} from './config.js';
const host=document.querySelector('#demo-host'),surface=document.querySelector('#demo-surface'),content=document.querySelector('#demo-content');
let currentTab='comments',rounds=2,selectedTheme='ダーク';
const messages=[['S','さくら','YouTube · 初見','はじめまして！ 配信楽しみにしてました。','lavender'],['H','はる','Twitch · 再訪','今日もよろしくお願いします！','blue'],['M','みなと','YouTube','参加希望！ 次のゲームも楽しみです。','blue']];
function element(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function drawDemo(){content.replaceChildren();if(currentTab==='comments'){const title=element('div','demo-feed-header');title.append(element('strong','','コメント'),element('span','','3件 / サンプル'));content.append(title);for(const [initial,name,service,text,color] of messages){const row=element('div','demo-message');const body=element('div');body.append(element('strong','',name),element('small','',service),element('p','',text));row.append(element('span','avatar '+color,initial),body);content.append(row);}}else if(currentTab==='queue'){content.append(element('div','demo-feed-header','参加受付中 · プレイ中 1人 / 待機 2人'));['さくら','はる','みなと'].forEach((name,i)=>{const row=element('div','demo-queue-row'),left=element('div');left.append(element('small','',i===0?'PLAYING':'WAITING'),element('strong','',name));row.append(left);if(i===0){const button=element('button','',rounds+' / 3回　＋1');button.onclick=()=>{rounds=rounds>=3?0:rounds+1;drawDemo();};row.append(button);}else row.append(element('span','','次の出番'));content.append(row);});}else if(currentTab==='overlay'){const preview=element('div','demo-obs');preview.append(element('span','','OBS BROWSER SOURCE'));const row=element('div','','さくら：配信の見た目も、自分らしく。');preview.append(row);content.append(preview);}else{const grid=element('div','demo-theme-grid');for(const [name,bg,fg] of [['ダーク','#252a3b','#e7ebf7'],['サクラ','#fff0f4','#71354f'],['ミント','#e2faf1','#1e6554'],['ネオン','#151332','#6bf2df']]){const button=element('button',selectedTheme===name?'selected':'',name);button.style.background=bg;button.style.color=fg;button.setAttribute('aria-pressed',String(selectedTheme===name));button.append(element('small','','YOUR STREAM, YOUR STYLE'));button.onclick=()=>{selectedTheme=name;surface.style.boxShadow='inset 0 0 0 2px '+(name==='ネオン'?'#6bf2df':name==='サクラ'?'#de91b4':name==='ミント'?'#64cfb2':'#8585b0');drawDemo();};grid.append(button);}content.append(grid,element('p','demo-help','15テーマを下地に、色・枠・角丸を自由に編集。'));}host.querySelector('canvas')?.requestPaint?.();}
for(const button of document.querySelectorAll('[data-demo-tab]'))button.addEventListener('click',()=>{currentTab=button.dataset.demoTab;for(const other of document.querySelectorAll('[data-demo-tab]'))other.setAttribute('aria-selected',String(other===button));drawDemo();});
drawDemo();
// Native HTML-in-Canvas, including both the pre-157 and current attribute names.
// Keep the very same live DOM as the fallback; links and controls remain accessible.
export function enableHtmlInCanvas(){const probe=document.createElement('canvas');const context=probe.getContext('2d');if(!context||typeof context.drawElementImage!=='function'||typeof probe.requestPaint!=='function'){host.dataset.rendering='dom';return false;}const canvas=probe;canvas.setAttribute('layoutsubtree','');canvas.setAttribute('content','drawable');canvas.setAttribute('aria-label','CastPanel インタラクティブプレビュー');surface.setAttribute('drawable','');let painted=false,failed=false;const fallback=()=>{if(failed)return;failed=true;host.append(surface);canvas.remove();surface.removeAttribute('drawable');surface.style.width='';surface.style.height='';surface.style.transform='';host.style.transform='';host.dataset.rendering='dom';};try{host.style.transform='none';host.replaceChildren(canvas);canvas.append(surface);const resize=()=>{if(failed)return;const box=host.getBoundingClientRect(),width=host.clientWidth||box.width,height=host.clientHeight||box.height;surface.style.width=width+'px';surface.style.height=height+'px';const ratio=typeof canvas.updateElementGeometry==='function'?Math.min(devicePixelRatio||1,2):1;canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);canvas.requestPaint();};canvas.addEventListener('paint',()=>{if(failed)return;try{context.clearRect(0,0,canvas.width,canvas.height);const geometry=context.drawElementImage(surface,0,0,canvas.width,canvas.height);if(typeof canvas.updateElementGeometry==='function')canvas.updateElementGeometry(surface,{canvasTransform:new DOMMatrix()});else if(geometry)surface.style.transform=geometry.toString();painted=true;host.dataset.rendering='html-in-canvas';}catch{fallback();}});new ResizeObserver(resize).observe(host);resize();document.fonts.ready.then(()=>canvas.requestPaint?.());setTimeout(()=>{if(!painted)fallback();},1800);return true;}catch{fallback();return false;}}
enableHtmlInCanvas();
function trustedDownload(url){try{const parsed=new URL(url);return parsed.protocol==='https:'&&parsed.hostname==='github.com'&&parsed.pathname.startsWith('/'+config.owner+'/'+config.repository+'/releases/download/');}catch{return false;}}
export function platformAssets(assets){const files=assets.filter(asset=>typeof asset.name==='string'&&trustedDownload(asset.browser_download_url));return {windows:files.find(a=>/\.exe$/i.test(a.name)&&!/portable|unpacked/i.test(a.name)),mac:files.find(a=>/\.dmg$/i.test(a.name)),linux:files.find(a=>/\.AppImage$/i.test(a.name))};}
async function loadRelease(){const status=document.querySelector('#release-status');document.querySelector('#releases-link').href=config.releasesUrl;try{const response=await fetch(config.releaseApi,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('No public release');const release=await response.json();if(release.draft||release.prerelease||!Array.isArray(release.assets))throw Error('Not a stable release');const assets=platformAssets(release.assets);let count=0;for(const [platform,asset] of Object.entries(assets)){if(!asset)continue;const link=document.querySelector('[data-download='+platform+']');link.href=asset.browser_download_url;link.removeAttribute('aria-disabled');link.textContent='ダウンロード ↓';count++;}status.textContent=count?'最新リリース '+String(release.tag_name||'').slice(0,60):'現在、公開済みのインストーラーはありません。';}catch{status.textContent='公開リリースは準備中です。GitHub Releasesから配布状況を確認できます。';}}
document.querySelector('#year').textContent=String(new Date().getFullYear());loadRelease();


